<?php
namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rules\Password;
class RegisterRequest extends FormRequest { public function authorize():bool{return true;} public function rules():array{return ['role'=>['required','in:worker,company'],'name'=>['required','string','max:120'],'email'=>['required','email','max:255','unique:users,email'],'phone'=>['required','string','max:30'],'password'=>['required','confirmed',Password::min(8)->mixedCase()->numbers()],'company_name'=>['required_if:role,company','nullable','string','max:150'],'city'=>['required','string','max:100']];} }
